Given two linked lists, the task is to check whether the first list is present in 2nd list or not. Examples:Input: list1 =  10->20, list2  = 5->10->20Output : YesExplanation: 5 -> 10 -> 20Input: list1 =  1->2, list2  = 1->2->1->2->3->4Output: YesExplanation: 1 -> 2 -> 1 -> 2 -> 3 -> 4Input: list1 =  1->2->3->4, list2  = 1->2->2->1->2->3Output: NoExplanation: List 1 is not present in List 2.[Naive Approach] Using Iterative Method - O(n * m) time and O(1) spaceThe idea is to use a nested loop approach where we consider each node in the second list as a potential starting point for finding the first list. For each such starting point, we try to match the sequences of both lists, advancing through them simultaneously, and if the entire first list can be traversed while matching values with a consecutive portion of the second list, then the first list is indeed a sub list of the second.
            C++

    // C++ program to search a linked list in another list
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node (int x) {
        data = x;
        next = nullptr;
    }
};

bool isSubList(Node* list1, Node* list2) {

    Node* head2 = list2;

    // Starting from each node of list2
    while (head2 != nullptr) {

        Node* head1 = list1;
        Node* curr = head2;

        // Check if list1 is present 
        // starting from node head2.
        while (curr != nullptr && head1 != nullptr
        && head1->data == curr->data) {
            curr = curr->next;
            head1 = head1->next;
        }

        // If list1 is completely traversed, it means 
        // it is present in list2.
        if (head1 == nullptr) return true;

        // Else, move to the next node of list2.
        head2 = head2->next;
    }

    // If list1 is not present in list2
    return false;
}

int main() {
    Node* list1 = new Node(10);
    list1->next = new Node(20);

    Node* list2 = new Node(5);
    list2->next = new Node(10);
    list2->next->next = new Node(20);

    if (isSubList(list1, list2)) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}


