    static ArrayList<Integer> constructLps(ArrayList<Integer> pattern) {
        int n = pattern.size();
        ArrayList<Integer> lps = new ArrayList<>(Collections.nCopies(n, 0));
        for (int i = 1, len = 0; i < n;) {
            if (pattern.get(i).equals(pattern.get(len))) {
                lps.set(i++, ++len);
            } else if (len > 0) {
                len = lps.get(len - 1);
            } else {
                lps.set(i++, 0);
            }
        }
