        int m = text.size(), n = pattern.size();

        ArrayList<Integer> lps = constructLps(pattern);

        for (int i = 0, j = 0; i < m;) {
            if (text.get(i).equals(pattern.get(j))) { 
                i++; j++;
            }

            // If end of pattern is reached
            if (j == n) {
                return true;
            }
            if (i < m && !text.get(i).equals(pattern.get(j))) {
                if (j != 0) {
